const statisticsHistory = `-- name: StatisticsHistory :many
SELECT
    status,
    completion_kind,
    (deleted_at IS NOT NULL)::BOOLEAN AS removed,
    COALESCE(deletion_kind, '')::TEXT AS deletion_kind,
    COUNT(*) AS count
FROM videos
WHERE status IN ('DONE', 'FAILED')
GROUP BY status, completion_kind, (deleted_at IS NOT NULL), COALESCE(deletion_kind, '')
`

type StatisticsHistoryRow struct {
	Status         string `json:"status"`
	CompletionKind string `json:"completion_kind"`
	Removed        bool   `json:"removed"`
	DeletionKind   string `json:"deletion_kind"`
	Count          int64  `json:"count"`
}

// Terminal recordings bucketed for the download-history tabs: by status, by
// completion kind, and by whether the media is still on disk. Cancelled runs
// are FAILED rows carrying completion_kind 'cancelled', so the SQL stays a
// plain group-by and the outcome vocabulary is folded in Go, where the rule
// lives once.
func (q *Queries) StatisticsHistory(ctx context.Context) ([]StatisticsHistoryRow, error) {
	rows, err := q.db.Query(ctx, statisticsHistory)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []StatisticsHistoryRow{}
	for rows.Next() {
		var i StatisticsHistoryRow
		if err := rows.Scan(
			&i.Status,
			&i.CompletionKind,
			&i.Removed,
			&i.DeletionKind,
			&i.Count,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const statisticsTotalsByBroadcaster = `-- name: StatisticsTotalsByBroadcaster :one
SELECT
    COUNT(*)::BIGINT AS total,
    COALESCE(SUM(size_bytes), 0)::BIGINT AS total_size,
    COALESCE(SUM(duration_seconds), 0)::DOUBLE PRECISION AS total_duration
FROM videos
WHERE broadcaster_id = $1 AND status = 'DONE' AND deleted_at IS NULL
`

type StatisticsTotalsByBroadcasterRow struct {
	Total         int64   `json:"total"`
	TotalSize     int64   `json:"total_size"`
	TotalDuration float64 `json:"total_duration"`
}

// Per-channel rollup of finished recordings: count + summed bytes +
// summed duration. Scopes the library totals to one broadcaster
// so the watch page can render a "N recordings · X GB" line under the
// channel name without paginating the full library client-side.
func (q *Queries) StatisticsTotalsByBroadcaster(ctx context.Context, broadcasterID string) (StatisticsTotalsByBroadcasterRow, error) {
	row := q.db.QueryRow(ctx, statisticsTotalsByBroadcaster, broadcasterID)
	var i StatisticsTotalsByBroadcasterRow
	err := row.Scan(&i.Total, &i.TotalSize, &i.TotalDuration)
	return i, err
}

